@props(['name'])

{{--
    One glyph per key used in config/navigation.php. Mirrors the `icons`
    object in resources/js/Layouts/AuthenticatedLayout.jsx key-for-key —
    the two can't share literal markup (Blade vs JSX), but must agree on
    which keys exist so every nav item renders on both stacks.
--}}
